class Solution:
    def calcTeamScores(self, teams, matches):
        res = []
        for tid, name in teams:
            pts = 0
            for _, h, g, hg, gg in matches:
                if tid == h:
                    pts += 3 if hg > gg else (1 if hg == gg else 0)
                elif tid == g:
                    pts += 3 if gg > hg else (1 if hg == gg else 0)
            res.append([tid, name, pts])
        res.sort(key=lambda x: (-x[2], x[0]))
        return res

