class Solution {
public:
    vector<vector<string>> calcTeamScores(vector<vector<int>>& teams,
                                          vector<vector<string>>& names,
                                          vector<vector<int>>& matches) {
        vector<tuple<int,string,int>> res;
        for (size_t i = 0; i < teams.size(); ++i) {
            int tid = teams[i][0], pts = 0;
            for (auto& m : matches) {
                int h = m[1], g = m[2], hg = m[3], gg = m[4];
                if (tid == h) pts += hg > gg ? 3 : (hg == gg ? 1 : 0);
                else if (tid == g) pts += gg > hg ? 3 : (hg == gg ? 1 : 0);
            }
            res.push_back({tid, names[i][0], pts});
        }
        sort(res.begin(), res.end(), [](auto& a, auto& b){
            if (get<2>(a) != get<2>(b)) return get<2>(a) > get<2>(b);
            return get<0>(a) < get<0>(b);
        });
        vector<vector<string>> out;
        for (auto& [id, nm, p] : res)
            out.push_back({to_string(id), nm, to_string(p)});
        return out;
    }
};

