class Solution {
    public List<List<String>> calcTeamScores(int[][] teams, String[][] names, int[][] matches) {
        int n = teams.length;
        int[] ids = new int[n]; int[] pts = new int[n];
        for (int i = 0; i < n; i++) ids[i] = teams[i][0];
        for (int i = 0; i < n; i++) {
            for (int[] m : matches) {
                int h = m[1], g = m[2], hg = m[3], gg = m[4];
                if (ids[i] == h) pts[i] += hg > gg ? 3 : (hg == gg ? 1 : 0);
                else if (ids[i] == g) pts[i] += gg > hg ? 3 : (hg == gg ? 1 : 0);
            }
        }
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> pts[b] != pts[a] ? pts[b] - pts[a] : ids[a] - ids[b]);
        List<List<String>> out = new ArrayList<>();
        for (int i : idx)
            out.add(Arrays.asList(String.valueOf(ids[i]), names[i][0], String.valueOf(pts[i])));
        return out;
    }
}

