var calcTeamScores = function(teams, matches) {
    const res = [];
    for (const [tid, name] of teams) {
        let pts = 0;
        for (const [, h, g, hg, gg] of matches) {
            if (tid === h) pts += hg > gg ? 3 : (hg === gg ? 1 : 0);
            else if (tid === g) pts += gg > hg ? 3 : (hg === gg ? 1 : 0);
        }
        res.push([tid, name, pts]);
    }
    res.sort((a, b) => b[2] - a[2] || a[0] - b[0]);
    return res;
};

